"""'What stands out': sentences generated by fixed rules from the numbers, in plain words. They
describe and never advise. Each item is (bold lead, rest); templates escape both."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from robby.audit.measures import (
    OE_HIGH,
    OE_LOW,
    UNCLASSIFIED_CALLOUT,
    Report,
)
from robby.audit.plain import SHORT_GROUPS, group_verdict, in_100

Item = tuple[str, str]
MOST_GROUPS_NAMED = 3


@dataclass(frozen=True)
class FacilityComparison:
    """One national-overview line, as numbers."""

    name: str
    births: int
    ratio: Decimal | None
    unclassified_pct: Decimal | None
    observed: Decimal | None = None
    expected: Decimal | None = None


def _names(names: list[str]) -> str:
    if len(names) == 1:
        return names[0]
    return ", ".join(names[:-1]) + f" and {names[-1]}"


def _group(g: int) -> str:
    return f"Group {g} ({SHORT_GROUPS[g]})"


def _largest_source(report: Report) -> list[Item]:
    """The group most cesareans come from (none when there are no cesareans)."""
    sources = sorted(
        (r for r in report.rows if r.cesareans and r.group),
        key=lambda r: (-r.cesareans, r.group or 0),
    )
    if not sources:
        return []
    top = sources[0]
    assert top.group is not None
    return [
        (
            f"Most cesareans come from {_group(top.group)}:",
            f" {top.cesareans} of the {report.cesareans} cesareans ({top.share_of_cs_pct}%).",
        )
    ]


def _against_reference(report: Report) -> list[Item]:
    """Groups with a higher rate than the reference, and groups larger than in it."""
    if report.reference is None:
        return [("No reference set loaded,", " so the groups are not compared with anything.")]
    items: list[Item] = []
    higher = [r for r in report.rows if group_verdict(r).css == "high"]
    higher.sort(key=lambda r: -r.cesareans)
    for r in higher[:MOST_GROUPS_NAMED]:
        assert r.group is not None
        items.append(
            (
                f"{_group(r.group)} has more cesareans than the reference:",
                f" {r.cesareans} of {r.births} women, {in_100(r.rate_pct)}, against "
                f"{in_100(r.ref_rate)} in the reference.",
            )
        )
    larger = [r.group for r in report.rows if r.larger_group and r.group]
    if larger:
        names = _names([str(g) for g in larger])
        items.append(
            (
                f"More women than usual are in group{'s' if len(larger) > 1 else ''} {names}.",
                " A group that is larger than in the reference adds cesareans even when its "
                "own rate is ordinary.",
            )
        )
    if not higher and not larger:
        items.append(("Every group is close to the reference.", ""))
    return items


def facility_stands_out(report: Report) -> list[Item]:
    if report.births == 0:
        return [("No births with a recorded outcome in this period.", "")]
    items = _largest_source(report) + _against_reference(report)
    if report.unclassified_high:
        items.append(
            (
                f"{report.residual.births} births ({report.unclassified_pct}%) could not be put "
                "in a Robson group,",
                " so the comparisons are less certain.",
            )
        )
    if report.awaiting:
        items.append(
            (
                f"{report.awaiting} admissions are still waiting for their delivery outcome",
                " and are not counted yet.",
            )
        )
    return items


def national_stands_out(rows: list[FacilityComparison], has_reference: bool) -> list[Item]:
    items: list[Item] = []
    if not has_reference:
        items.append(
            (
                "No reference set loaded,",
                " so expected rates cannot be worked out; each hospital's own figures are shown.",
            )
        )
    else:
        for r in rows:
            if r.ratio is None:
                continue
            if r.ratio >= OE_HIGH or r.ratio <= OE_LOW:
                more = r.ratio >= OE_HIGH
                items.append(
                    (
                        f"{r.name} has {'more' if more else 'fewer'} cesareans than expected "
                        "for the women it sees:",
                        f" {in_100(r.observed)}, where {in_100(r.expected)} would be expected.",
                    )
                )
        close = [r.name for r in rows if r.ratio is not None and OE_LOW < r.ratio < OE_HIGH]
        if close:
            items.append(
                (
                    f"{_names(close)} {'is' if len(close) == 1 else 'are'} close to what is "
                    "expected for the women they see.",
                    "",
                )
            )
    high = [
        r.name for r in rows if r.unclassified_pct and r.unclassified_pct > UNCLASSIFIED_CALLOUT
    ]
    if high:
        items.append(
            (
                f"{_names(high)} could not put more than {UNCLASSIFIED_CALLOUT:.0f}% of births "
                "in a Robson group,",
                " so comparisons for them are less certain.",
            )
        )
    if not items:
        items.append(("No hospital has births with a recorded outcome in this period.", ""))
    return items
